function extract($, ctx) {
  const items = [];
  const seen = new Set();

  $('script[type="application/ld+json"]').each((_, el) => {
    let raw;
    try {
      raw = $(el).text();
    } catch (_) {
      return;
    }
    let data;
    try {
      data = JSON.parse(raw);
    } catch (_) {
      return;
    }
    const menuList = Array.isArray(data) ? data : [data];
    for (const obj of menuList) {
      if (!obj || obj['@type'] !== 'Menu') continue;
      const sections = obj.hasMenuSection || [];
      for (const sec of sections) {
        const sectionName = sec.name ?? null;
        const menuItems = sec.hasMenuItem || [];
        for (const it of menuItems) {
          const nameRaw = it.name ?? '';
          const name = cleanText(nameRaw);
          if (!name) continue;

          const descRaw = it.description ?? null;
          const description = descRaw !== null ? cleanText(descRaw) : null;

          let priceStr = null;
          const offers = it.offers;
          if (offers) {
            let offerObj = null;
            if (Array.isArray(offers)) {
              offerObj = offers[0] || null;
            } else if (typeof offers === 'object') {
              offerObj = offers;
            }
            if (offerObj && offerObj.price !== undefined) {
              priceStr = String(offerObj.price);
            }
          }
          const price = priceStr !== null ? parsePrice(priceStr) : null;

          const key = JSON.stringify({section: sectionName, name, description, price});
          if (seen.has(key)) continue;
          seen.add(key);
          items.push({section: sectionName, name, description, price});
        }
      }
    }
  });

  return items;
}
